import csv
import io


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)

    while len(columns) < width:
        base = "column_" + str(len(columns) + 1)
        name = base
        suffix = 2
        while name in used:
            name = base + "_" + str(suffix)
            suffix += 1
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
